window.__code__["code-w10-tool-guard-yaml"] = {"code_id": "code-w10-tool-guard-yaml", "kind": "local", "title": "tool_guard.yaml", "source_path": "/Users/zhongyou/Desktop/2027年/code/w10/tool_guard.yaml", "highlight_line": null, "code_html": "<pre># code/w10/tool_guard.yaml\n# ============================================================\n# W10 作业2:仿 QwenPaw security/tool_guard,用 YAML 声明工具调用拦截规则\n# 对照 QwenPaw security/tool_guard/execution_level.py 四档:\n#   STRICT(全审批) / SMART(低危放行中危+审批) / AUTO(仅guarded审批) / OFF(关)\n# 配套代码:code/w10/tool_guard_demo.py 解析本文件并判定\n# ============================================================\n# 全局执行级别(可被单条规则覆盖)\nexecution_level: smart   # strict | smart | auto | off\n\nrules:\n  # 直接拒绝:递归删除根/家目录/通配 —— 绝不允许\n  - name: block-destructive-rm\n    pattern: &#x27;rm\\s+-rf?\\s+(/|~|\\*|\\.\\.)&#x27;\n    level: deny\n    message: &quot;禁止递归删除根/家目录/上级目录&quot;\n\n  # 直接拒绝:下载即执行 —— 典型 prompt 注入逃逸\n  - name: block-pipe-exec\n    pattern: &#x27;(curl|wget)[^\\|]*\\|\\s*(sh|bash|zsh)&#x27;\n    level: deny\n    message: &quot;禁止管道下载即执行&quot;\n\n  # 需审批:sudo 提权 —— SMART/AUTO 下走审批流(对应 ApprovalService)\n  - name: warn-sudo\n    pattern: &#x27;\\bsudo\\b&#x27;\n    level: ask\n    message: &quot;sudo 操作需确认&quot;\n\n  # 需审批:写系统目录\n  - name: warn-system-write\n    pattern: &#x27;(/\\&gt;|&gt;&gt;?)\\s*(/etc|/usr|/bin|/System)&#x27;\n    level: ask\n    message: &quot;写系统目录需确认&quot;</pre>", "lines": 34, "explanation": "tool_guard.yaml 是本教程的可运行示例代码，示范对应周次核心概念；顶部注释含运行前置依赖与预期输出，建议结合左侧源码与对应周文档「动手作业」一起读。", "knowledge_points": [{"title": "权限与沙箱", "body": "PolicyGuardedTool 策略引擎 + STRICT/SMART/AUTO/OFF 四档执行级别 + 内核级沙箱（macOS Seatbelt / Linux bubblewrap·landlock / Windows AppContainer）防 prompt 注入逃逸；ApprovalService 人在回路。"}], "related_docs": ["W10-Loop-Engineering与治理沙箱安全"]};
